Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define ULL unsigned LL
#define PII pair<int,int>
#define PB push_back
#define MP make_pair
#define INF 1000000000
#define MOD 1000000007

int shortestPath[15][15][15][15];
int capacityMatrix[400][400];
char scienceMap[20][20];
char reactionMap[20][20];
int dirX[] = {1, 0, -1, 0};
int dirY[] = {0, 1, 0, -1};
int currentVisit = 3;
int visitedNodes[400];

int n, tLimit;
int dfsAugment(int cnode, int dest, int flow) {
    if (cnode == dest) return flow;
    if (visitedNodes[cnode] == currentVisit) return 0;
    visitedNodes[cnode] = currentVisit;
    for (int i = 0; i <= dest; i++) {
        if (capacityMatrix[cnode][i] > 0) {
            int pushed = dfsAugment(i, dest, min(flow, capacityMatrix[cnode][i]));
            if (pushed > 0) {
                capacityMatrix[cnode][i] -= pushed;
                capacityMatrix[i][cnode] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int nodeID(int x, int y) {
    return (x - 1) * n + y - 1;
}

int reachStates[13][13], tempStates[13][13];

void propagate(int val) {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            tempStates[i][j] = reachStates[i][j];

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (tempStates[i][j] == val) {
                for (int d = 0; d < 4; d++) {
                    int ni = i + dirX[d], nj = j + dirY[d];
                    if (ni > 0 && nj > 0 && ni <= n && nj <= n && reachStates[ni][nj] < val && scienceMap[ni][nj] != 'Y') {
                        reachStates[ni][nj] = val;
                    }
                }
            }
        }
    }
}

bool isReachable(int sx, int sy, int tx, int ty, int ix, int iy) {
    memset(reachStates, 0, sizeof(reachStates));
    reachStates[sx][sy] = 1;
    reachStates[ix][iy] = 2;
    for (int i = 0; i < 100; i++) {
        propagate(1);
        if (reachStates[tx][ty] == 1) return true;
        propagate(2);
        if (reachStates[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    int infX, infY;
    memset(shortestPath, 1, sizeof(shortestPath));
    cin >> n >> tLimit;
    for (int i = 1; i <= n; i++) {
        scanf(" %s", scienceMap[i] + 1);
        for (int j = 1; j <= n; j++) {
            shortestPath[i][j][i][j] = 0;
            if (scienceMap[i][j] == 'Z') {
                infX = i; infY = j;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        scanf(" %s", reactionMap[i] + 1);
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            for (int d = 0; d < 4; d++) {
                int ni = i + dirX[d], nj = j + dirY[d];
                if (ni > 0 && ni <= n && nj > 0 && nj <= n) {
                    if (scienceMap[i][j] != 'Y' && scienceMap[ni][nj] != 'Y') {
                        shortestPath[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }
    for (int ki = 1; ki <= n; ki++) {
        for (int kj = 1; kj <= n; kj++) {
            for (int ii = 1; ii <= n; ii++) {
                for (int ij = 1; ij <= n; ij++) {
                    for (int ji = 1; ji <= n; ji++) {
                        for (int jj = 1; jj <= n; jj++) {
                            shortestPath[ii][ij][ji][jj] = min(
                                shortestPath[ii][ij][ji][jj],
                                shortestPath[ii][ij][ki][kj] + shortestPath[ki][kj][ji][jj]
                            );
                        }
                    }
                }
            }
        }
    }
    int srcNode = n * n * 2 + 1;
    int sinkNode = n * n * 2 + 2;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (isdigit(scienceMap[i][j])) {
                capacityMatrix[srcNode][nodeID(i, j)] = scien[i][j] - '0';
            }
            if (isdigit(reactionMap[i][j])) {
                capacityMatrix[n * n + nodeID(i, j)][sinkNode] = reac[i][j] - '0';
            }
            if (isdigit(scienceMap[i][j])) {
                for (int ki = 1; ki <= n; ki++) {
                    for (int kj = 1; kj <= n; kj++) {
                        if (scien[i][j] > '0' && reac[ki][kj] > '0') {
                            if (isdigit(reac[ki][kj]) && shortestPath[i][j][ki][kj] <= tLimit && isReachable(i, j, ki, kj, infX, infY)) {
                                capacityMatrix[nodeID(i, j)][n * n + nodeID(ki, kj)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }
    int totalFlow = 0, flowVal;
    while ((flowVal = dfsAugment(srcNode, sinkNode, 1000)) > 0) {
        totalFlow += flowVal;
        currentVisit++;
    }
    cout << totalFlow << endl;
    return 0;
}
